def load_png(folder, name):
    img = bpy.data.images.load(os.path.join(folder, name))
    img.colorspace_settings.name = 'Non-Color'
    return read(img), img


tol = 2.0 / 255 + 1e-4
orm, orm_img = load_png(out_dir, "T_Low_ORM.png")
check(tuple(orm_img.size) == (128, 128), "ORM is 128 px")
