check(np.abs(orm[:, 1] - ramp).max() < tol, "ORM green is the roughness map (error %s)" % np.abs(orm[:, 1] - ramp).max())
check(np.abs(orm[:, 2] - ramp_back).max() < tol, "ORM blue is the metallic map (error %s)" % np.abs(orm[:, 2] - ramp_back).max())
