check(abs(normal_out[0, 1] - 0.3) < tol and abs(normal_out[0, 0] - 0.5) < tol, "Unreal normal map has the green channel flipped: %s" % normal_out[0])
base_out, _ = load_png(out_dir, "T_Low_BC.png")
