res_ = bpy.ops.m3d.rig_bind()
check(res_ == {'FINISHED'} and R.is_bound(body) and R.unweighted(body, rig) == 0, "bind again, mesh and skeleton selected: %s %s %s" % (res_, R.is_bound(body), R.unweighted(body, rig)))

