    for key in ('RIG_SKELETON', 'RIG_CONTROLS', 'RIG_SKIN', 'CUSTOM'):
        log = []
        bpy.context.window_manager.m3d_shelf = key
        m3d_ui.draw_shelf(Rec(log), RCtx())
