    others = [(km.name, k.idname) for km in kc.keymaps for k in km.keymap_items
              if k.type == 'F12' and all(getattr(k, m) == v for m, v in mods.items()) and not k.oskey and not k.any
              and not k.idname.startswith("m3d.render")]
