check(E.shelf_hit(rec_, 50, 120) == ("C", 1) and E.shelf_hit(rec_, 126, 120) is None and E.shelf_hit(rec_, 150, 120) == ("C", 3)
      and E.shelf_hit(rec_, 50, 300) is None and E.shelf_hit(rec_, 900, 120) is None, "shelf hit test")
