def idm_scene(uv=(0.0, 0.0, 1.0, 1.0), margin=4, two_objects=False):
    clean_scene()
    for m in [m for m in bpy.data.materials if m.name.split(".")[0] in {"MatA", "MatB"}]:
        bpy.data.materials.remove(m)
    for entry in list(bpy.context.scene.m3d_bake_groups):
        bpy.context.scene.m3d_bake_groups.remove(0)
    low = bg_plate("Id_low", uv=uv, role='LOW', group="Id")
    mats = [bpy.data.materials.new("MatA"), bpy.data.materials.new("MatB")]
    if two_objects:   # (one material: a colour for each mesh)
        left = bg_plate("Id_high", x=-0.5, size=1.0, res=3, role='HIGH', group="Id")
        right = bg_plate("Id_high_b", x=0.5, size=1.0, res=3, role='HIGH', group="Id")
        highs = [left, right]
        for h in highs:
            h.data.materials.append(mats[0])
    else:   # (two materials on one mesh: left half and right half)
        high = bg_plate("Id_high", res=8, bump=0.1, role='HIGH', group="Id")
        high.data.materials.append(mats[0])
        high.data.materials.append(mats[1])
        for poly in high.data.polygons:
            poly.material_index = 0 if sum(high.data.vertices[i].co.x for i in poly.vertices) < 0 else 1
        highs = [high]
    s = low.m3d_bake
    s.resolution, s.margin, s.samples, s.extrusion = '64', margin, 8, 0.5
    s.use_normal = s.use_ao = False
    s.use_id = True
    PR.park_all(bpy.context)
    bpy.context.view_layer.objects.active = low
    low.select_set(True)
    return low, highs, mats


idm_low, idm_highs, idm_mats = idm_scene()
idm_flags = bg_flags()
check(bpy.ops.m3d.bg_bake() == {'FINISHED'}, "Bake Group with only the ID map ticked")
check(bg_flags() == idm_flags, "(everything is put back, the temporary materials are gone, the materials of the high poly are back)")
check([s.material.name for s in idm_highs[0].material_slots] == ["MatA", "MatB"], "the high poly has its own materials again")
idm_img = bpy.data.images["Id_low_ID"]
idm_px = read_image(idm_img)
idm_a, idm_b = np.array(T.id_color(0), np.float32), np.array(T.id_color(1), np.float32)
check(idm_img.colorspace_settings.name == 'Non-Color' and T.map_image(idm_low, "ID") == idm_img, "the ID map is a data image named like the others, found by map_image")
check(np.abs(idm_px[:, :32, :3] - idm_a).max() < 0.005 and np.abs(idm_px[:, 32:, :3] - idm_b).max() < 0.005,
      "the left half of the low poly has the colour of MatA, the right half the one of MatB (%.4f)" % max(np.abs(idm_px[:, :32, :3] - idm_a).max(), np.abs(idm_px[:, 32:, :3] - idm_b).max()))
check(len(np.unique(np.round(idm_px[..., :3], 3).reshape(-1, 3), axis=0)) == 2, "...and nothing else: no colour in between, also along the edge between them")
check({k: tuple(round(x, 4) for x in v) for k, v in MK.id_colors(idm_img).items()} == {"Id: MatA": tuple(round(float(x), 4) for x in idm_a), "Id: MatB": tuple(round(float(x), 4) for x in idm_b)}
      and [m.name for m in idm_mats] == ["MatA", "MatB"],
      "the image says which colour is which: %s" % MK.id_colors(idm_img))
bpy.ops.m3d.bg_bake()
check(np.array_equal(read_image(idm_img), idm_px), "a new bake gives the same colours")
# The materials are named after, not ordered by, the slots: swap the slots
idm_highs[0].data.materials[0], idm_highs[0].data.materials[1] = idm_mats[1], idm_mats[0]
for poly in idm_highs[0].data.polygons:
    poly.material_index = 1 - poly.material_index
bpy.ops.m3d.bg_bake()
check(np.array_equal(read_image(idm_img), idm_px), "...also with the slots in another order (the colour is the material's)")

# A mesh with one material or none: a colour for each mesh
idm_low, idm_highs, idm_mats = idm_scene(two_objects=True)
check(bpy.ops.m3d.bg_bake() == {'FINISHED'}, "Bake Group: two high polys with one material")
idm_px = read_image(bpy.data.images["Id_low_ID"])
check(np.abs(idm_px[20:44, :30, :3] - idm_a).max() < 0.005 and np.abs(idm_px[20:44, 34:, :3] - idm_b).max() < 0.005 and idm_px[:8, :, :3].max() == 0.0,
      "each mesh has a colour, in the order of their names: Id_high, Id_high_b (and black where no mesh is)")
for h in idm_highs:
    h.data.materials.clear()
bpy.ops.m3d.bg_bake()
check(np.abs(read_image(bpy.data.images["Id_low_ID"])[20:44, :, :3] - idm_px[20:44, :, :3]).max() < 0.005, "...also without any material")

# The margin extends the colours, it does not blend them
idm_low, idm_highs, idm_mats = idm_scene(uv=(0.0, 0.0, 0.5, 1.0), margin=8)
bpy.ops.m3d.bg_bake()
idm_px = read_image(bpy.data.images["Id_low_ID"])[..., :3]
idm_near = np.minimum(np.abs(idm_px - idm_a).max(axis=-1), np.abs(idm_px - idm_b).max(axis=-1))
idm_black = idm_px.max(axis=-1) < 0.001
idm_other = ~idm_black & (idm_near >= 0.005)
check(idm_black.sum() > 500 and not idm_other[:, :34].any() and idm_other.sum() <= 64,
      "the margin extends the colours, it does not blend them: every pixel is black or exactly a colour of the model, but the last pixel of the margin (%d black, %d blended)" % (idm_black.sum(), idm_other.sum()))
check(not idm_black[:, :32].any() and idm_black[:, 41:].all(), "...and past the margin it is black")

# The Color ID mask picks one of them
idm_low, idm_highs, idm_mats = idm_scene()
bpy.context.scene.m3d_tex.resolution = '64'
bpy.ops.m3d.tex_add_material()
idm_mat = idm_low.active_material
with LY.muted():
    LY.add_layer(idm_mat, 'PAINT', "Base")
    LY.add_layer(idm_mat, 'FILL', "Top")
    idm_mat.m3d_layer_index = 1
LY.rebuild_all(idm_mat)
idm_top = idm_mat.m3d_layers[1]
if "Id_low_ID" in bpy.data.images:   # (the maps of the tests above are not this scene's)
    bpy.data.images.remove(bpy.data.images["Id_low_ID"])
idm_menu = []
T.M3D_MT_mask_add.draw(type("Inst", (), {"layout": Rec(idm_menu)})(), bpy.context)
check("COLORID" in [r.kind for r in idm_menu if r._kind == "operator"], "Add Mask Effect lists Color Selection (Color ID)")
check(bpy.ops.m3d.mask_effect_add(kind='COLORID') == {'FINISHED'}, "add a Color ID effect (it bakes the ID map)")
idm_e = idm_top.mask_stack[0]
idm_img = bpy.data.images.get("Id_low_ID")
check(idm_e.kind == 'COLORID' and idm_e.image == idm_img and not MK.missing_maps(idm_top), "it reads the ID map of the low poly's group: %s" % idm_e.image)
check(tuple(round(x, 4) for x in idm_e.color) == tuple(round(float(x), 4) for x in idm_a), "...and starts with the first colour")
idm_mask = MK.stack_value(idm_top, 64)
check(idm_mask[:, :32].min() > 0.99 and idm_mask[:, 32:].max() < 0.01, "the mask is white on the region of MatA and black elsewhere")
check(bpy.ops.m3d.mask_id_pick(name="Id: MatB") == {'FINISHED'} and tuple(round(x, 4) for x in idm_e.color) == tuple(round(float(x), 4) for x in idm_b), "Pick ID Colour sets the colour of a material")
idm_mask = MK.stack_value(idm_top, 64)
check(idm_mask[:, 32:].min() > 0.99 and idm_mask[:, :32].max() < 0.01, "...and the mask is the other region")
check(bpy.ops.m3d.mask_id_pick(name="Nothing") == {'CANCELLED'}, "an unknown name is refused")
idm_e.color = (0.5, 0.5, 0.5)
check(MK.stack_value(idm_top, 64).max() < 0.01, "a colour that is not in the map selects nothing")
idm_e.color = (0.6, 0.3, 0.6)   # (a colour between the two, about 0.57 from each)
idm_e.tolerance = 0.3
check(MK.stack_value(idm_top, 64).max() < 0.01, "a colour that is further from the colours of the map than the tolerance selects nothing")
idm_e.tolerance = 1.0
idm_soft = MK.stack_value(idm_top, 64)
check(idm_soft.min() > 0.7 and idm_soft.max() < 1.0, "...a wide tolerance lets both in, a little less than fully (%.2f)" % idm_soft.mean())
idm_e.color = tuple(idm_a)
idm_e.tolerance = 0.1
node = LY.mask_node(idm_mat.node_tree, idm_top, "tex", idm_e)
check(node is not None and node.interpolation == 'Closest' and node.image == idm_img, "the ID map is read without blending the texels")
grp = LY.mask_node(idm_mat.node_tree, idm_top, "grp", idm_e)
check(grp is not None and grp.node_tree.name == "m3d_mask.colorid" and tuple(round(x, 4) for x in grp.inputs["Color"].default_value) == tuple(round(float(x), 4) for x in idm_a)
      and abs(grp.inputs["Tolerance"].default_value - 0.1) < 1e-6, "the node group has the colour and the tolerance")
log = bg_draw(T.PROPERTIES_PT_m3d_tx_mask)
idm_pick = [r._kw["text"] for r in log if r._kind == "operator" and r._args[0] == "m3d.mask_id_pick"]
check(idm_pick == ["Id: MatA", "Id: MatB"], "the Mask panel lists the colours of the ID map to pick: %s" % idm_pick)
check(["color", "tolerance"] == [r._args[1] for r in log if r._kind == "prop" and r._args[1] in {"color", "tolerance"}], "...with the colour and the tolerance")

# --- Shift / Ctrl + double-click an edge: the edges between it and the edge selected before, along a ring or a loop.
clean_scene()
bpy.ops.mesh.primitive_grid_add(x_subdivisions=6, y_subdivisions=6, size=6)   # 6 x 6 quads of 1 x 1
eb_ob = bpy.context.active_object
bpy.ops.object.mode_set(mode='EDIT')
bpy.ops.mesh.select_mode(type='EDGE')
eb_bm = bmesh.from_edit_mesh(eb_ob.data)


def eb_edge(x, y):
    """The edge whose midpoint is at (x, y)."""
    return next(e for e in eb_bm.edges if (abs((e.verts[0].co.x + e.verts[1].co.x) / 2 - x) < 1e-4
                                          and abs((e.verts[0].co.y + e.verts[1].co.y) / 2 - y) < 1e-4))


def eb_mids(edges):
    return sorted((round((e.verts[0].co.x + e.verts[1].co.x) / 2, 2), round((e.verts[0].co.y + e.verts[1].co.y) / 2, 2))
                  for e in edges)


# Horizontal edges (midpoints at x = -2.5 ... 2.5, y = -3 ... 3): a ring runs up a column, a loop along a row.
eb_a = eb_edge(-0.5, -3.0)
check(eb_mids(_mm.edges_between(eb_a, eb_edge(-0.5, 0.0))) == [(-0.5, y) for y in (-3.0, -2.0, -1.0, 0.0)],
      "edges between: a partial ring up to the second edge")
check(len(_mm.edges_between(eb_a, eb_edge(-0.5, -2.0))) == 7, "...the next edge of the ring: the whole ring (7 edges)")
check(eb_mids(_mm.edges_between(eb_a, eb_edge(1.5, -3.0))) == [(x, -3.0) for x in (-0.5, 0.5, 1.5)],
      "...an edge further along the loop: a partial loop")
check(len(_mm.edges_between(eb_a, eb_edge(0.5, -3.0))) == 6, "...the next edge of the loop: the whole loop (6 edges)")
check(_mm.edges_between(eb_a, eb_edge(1.5, 1.0)) is None, "...an edge on neither: None")
# The operator: the edges between join the selection; the second edge becomes the active one.
bpy.ops.mesh.select_all(action='DESELECT')
eb_bm.select_history.clear()
for eb_e in (eb_a, eb_edge(-0.5, 1.0)):
    eb_e.select_set(True)
    eb_bm.select_history.add(eb_e)
check(bpy.ops.m3d.select_edges_between() == {'FINISHED'}
      and eb_mids(e for e in eb_bm.edges if e.select) == [(-0.5, y) for y in (-3.0, -2.0, -1.0, 0.0, 1.0)]
      and eb_bm.select_history.active == eb_edge(-0.5, 1.0), "Select Edges Between: the partial ring is selected")
# Deselect (Ctrl): the edges between go, a selected edge that shares their points keeps its points.
bpy.ops.mesh.select_all(action='DESELECT')
eb_bm.select_history.clear()
eb_keep = eb_edge(-1.0, -1.5)   # (vertical, shares a point with the ring edge at y = -1)
for eb_e in (eb_keep, *(eb_edge(-0.5, y) for y in (-3.0, -2.0, -1.0, 0.0, 1.0))):
    eb_e.select_set(True)
eb_bm.select_history.add(eb_edge(-0.5, -2.0))
eb_bm.select_history.add(eb_edge(-0.5, 0.0))
check(bpy.ops.m3d.select_edges_between(deselect=True) == {'FINISHED'}
      and eb_mids(e for e in eb_bm.edges if e.select) == sorted([(-1.0, -1.5), (-0.5, -3.0), (-0.5, 1.0)])
      and all(v.select for v in eb_keep.verts), "...Ctrl: the edges between are deselected, a neighbour keeps its points")
bpy.ops.mesh.select_all(action='DESELECT')
eb_bm.select_history.clear()
eb_a.select_set(True)
eb_bm.select_history.add(eb_a)
eb_edge(1.5, 1.0).select_set(True)
eb_bm.select_history.add(eb_edge(1.5, 1.0))
check(bpy.ops.m3d.select_edges_between() == {'CANCELLED'}, "...on neither ring nor loop: nothing (the click selects its loop)")
bpy.ops.object.mode_set(mode='OBJECT')
# A closed ring (the sides of a cylinder): the shorter way round.
clean_scene()
bpy.ops.mesh.primitive_cylinder_add(vertices=12)
bpy.ops.object.mode_set(mode='EDIT')
eb_bm = bmesh.from_edit_mesh(bpy.context.active_object.data)
eb_sides = sorted((e for e in eb_bm.edges if abs(e.verts[0].co.z - e.verts[1].co.z) > 1),
                  key=lambda e: math.atan2(e.verts[0].co.y, e.verts[0].co.x))
check(len(_mm.edges_between(eb_sides[0], eb_sides[3])) == 4 and len(_mm.edges_between(eb_sides[0], eb_sides[9])) == 4
      and len(_mm.edges_between(eb_sides[0], eb_sides[1])) == 12, "...a closed ring: the shorter way round; neighbours: all 12")
bpy.ops.object.mode_set(mode='OBJECT')

# ----------------------------------------------------------------------------------------------------
# Multi-channel painting: the brush material (Scene.m3d_tex.brush), the list of what one stroke paints that the paint code reads
# (the window manager's m3d_paint_targets), the images it needs. The strokes themselves are tested in gui_test.py.
tex_ws = bpy.data.workspaces["Texture"]   # (files were opened since: the workspaces are new)
mc_wm = bpy.context.window_manager
mc_brush = bpy.context.scene.m3d_tex.brush
MC_VALUES = {'use_base_color': True, 'use_height': False, 'use_roughness': False, 'use_metallic': False, 'use_emission': False,
             'height': 0.5, 'roughness': 0.5, 'metallic': 0.0, 'emission': (0.0, 0.0, 0.0)}


def mc_reset():
    with LY.muted():
        for key, value in MC_VALUES.items():
            setattr(mc_brush, key, value)


def mc_list():
    """[(image name, color or None)] of the list the paint code reads (empty without one)."""
    items = mc_wm.get(LY.TARGETS)
    return [(i["image"], tuple(i["color"].to_list()) if "color" in i else None) for i in items] if items is not None else []


def mc_names(layer, *channels):
    return [LY.entry_of(layer, c).image.name for c in channels]


mc_reset()
check(all(getattr(mc_brush, k) == v if k != 'emission' else tuple(mc_brush.emission) == v for k, v in MC_VALUES.items()),
      "the brush material starts with Base Color on, the other channels off")
check("normal" not in " ".join(p.identifier for p in mc_brush.bl_rna.properties), "the brush material has no Normal channel")
o, m = fresh_cube("Multi", '64')
check(bpy.ops.m3d.layer_add(kind='PAINT') == {'FINISHED'}, "(a paint layer)")
layer = m.m3d_layers[0]
check(LY.entry_of(layer, 'BASE_COLOR').image is not None and sum(e.image is not None for e in layer.channels) == 1
      and mc_list() == [(LY.entry_of(layer, 'BASE_COLOR').image.name, None)],
      "Base Color only: its image is made, the list names it without a color (%s)" % mc_list())
check(slot_image(m) == LY.entry_of(layer, 'BASE_COLOR').image, "...and it is the canvas (the active paint slot)")

# Turn channels on: the layer makes their images, at the size of its other images; the list has the values.
mc_brush.roughness, mc_brush.metallic, mc_brush.height = 0.2, 1.0, 0.8
mc_brush.use_roughness = mc_brush.use_metallic = mc_brush.use_height = True
names = mc_names(layer, 'BASE_COLOR', 'ROUGHNESS', 'METALLIC', 'HEIGHT')
want = [(names[0], None)] + [(n, (v,) * 3) for n, v in zip(names[1:], (0.2, 1.0, 0.8))]
got = mc_list()
check(len(got) == 4 and [n for n, _c in got] == names and got[0][1] is None
      and all(np.allclose(g[1], w[1], atol=1e-6) for g, w in zip(got[1:], want[1:])),
      "Base Color, Roughness, Metallic and Height on: the list is %s" % got)
check(all(tuple(LY.entry_of(layer, c).image.size) == (64, 64) for c in ('BASE_COLOR', 'ROUGHNESS', 'METALLIC', 'HEIGHT'))
      and LY.entry_of(layer, 'EMISSION').image is None and LY.entry_of(layer, 'NORMAL').image is None,
      "...the images have one size, and channels that are off have none")
check(LY.entry_of(layer, 'ROUGHNESS').image.colorspace_settings.name == 'Non-Color'
      and LY.entry_of(layer, 'HEIGHT').image.colorspace_settings.name == 'Non-Color'
      and LY.entry_of(layer, 'BASE_COLOR').image.colorspace_settings.name == 'sRGB', "...in the color spaces of the channels")
check(slot_image(m) == LY.entry_of(layer, 'BASE_COLOR').image and all(LY.entry_of(layer, c).image in list(m.texture_paint_images)
                                                                       for c in ('ROUGHNESS', 'METALLIC', 'HEIGHT')),
      "...the canvas is the Base Color image, and the others are in the chains (paint slots)")
mc_brush.height = 0.65
check(abs(mc_list()[3][1][0] - 0.65) < 1e-6, "changing a value rewrites the list (%s)" % mc_list())
mc_brush.use_emission = True
mc_brush.emission = (0.5, 0.2, 0.1)
got = mc_list()
check(len(got) == 5 and got[4][0] == LY.entry_of(layer, 'EMISSION').image.name and np.allclose(got[4][1], (0.5, 0.2, 0.1), atol=1e-6)
      and LY.entry_of(layer, 'EMISSION').image.colorspace_settings.name == 'sRGB', "Emission: its color is in the list (linear)")
mc_brush.use_emission = False

# The Eraser has no channels of its own: the list is the same (the stroke's blend erases every image of it).
bpy.ops.m3d.tex_tool(tool='ERASER')
check(len(mc_list()) == 4, "the Eraser erases the channels that are on: the same list")
bpy.ops.m3d.tex_tool(tool='PAINT')

# The first channel that is on is the canvas, and gets its own value (the brush color is Base Color's).
mc_brush.use_base_color = False
got = mc_list()
check([n for n, _c in got] == names[1:] and np.allclose(got[0][1], (0.2,) * 3) and slot_image(m) == LY.entry_of(layer, 'ROUGHNESS').image,
      "Base Color off: Roughness is the canvas and keeps its value (%s)" % got)
mc_brush.use_roughness = mc_brush.use_metallic = False
got = mc_list()
check(len(got) == 1 and got[0][0] == names[3] and np.allclose(got[0][1], (0.65,) * 3) and slot_image(m) == LY.entry_of(layer, 'HEIGHT').image,
      "...even alone (%s)" % got)
mc_brush.use_base_color = True

# A channel the layer does not have is not painted; turning it on gives it back.
with LY.muted():
    LY.entry_of(layer, 'HEIGHT').use = False
LY.sync_target(bpy.context, m, True)
check(names[3] not in [n for n, _c in mc_list()], "a channel the layer does not have is not in the list")
mc_brush.use_height = False
mc_brush.use_height = True
check(LY.entry_of(layer, 'HEIGHT').use and names[3] in [n for n, _c in mc_list()], "...turning the channel on in the brush material gives it back")

# Selecting a channel to show (C) does not change what is painted; picking one to paint does.
mc_brush.use_roughness = mc_brush.use_metallic = True
before_ = (mc_list(), {k: getattr(mc_brush, k) for k in MC_VALUES if k != 'emission'})
T.select_channel(m, 'METALLIC')
check(m.m3d_channel == 'METALLIC' and mc_list() == before_[0] and before_[1] == {k: getattr(mc_brush, k) for k in MC_VALUES if k != 'emission'},
      "C only shows a channel: the list and the toggles stay (%s)" % mc_list())
check(bpy.ops.m3d.tex_channel(channel='ROUGHNESS') == {'FINISHED'} and m.m3d_channel == 'ROUGHNESS'
      and [k for k in MC_VALUES if k.startswith("use_") and getattr(mc_brush, k)] == ['use_roughness']
      and [n for n, _c in mc_list()] == [names[1]] and np.allclose(mc_list()[0][1], (0.2,) * 3), "Paint Roughness paints that channel alone (%s)" % mc_list())
check(bpy.ops.m3d.tex_channel(channel='NORMAL') == {'FINISHED'} and not mc_list() and slot_image(m) == LY.entry_of(layer, 'NORMAL').image
      and not any(k.startswith("use_") and getattr(mc_brush, k) for k in MC_VALUES),
      "Normal is not in the brush material: it is painted alone (no list, the canvas is its image)")
check(bpy.ops.m3d.tex_channel(channel='BASE_COLOR') == {'FINISHED'} and mc_list() == [(names[0], None)], "Paint Base Color: back to the brush color")

# Paint Mask, a fill layer and a folder have no list.
mc_brush.use_roughness = True
check(len(mc_list()) == 2, "(two channels again)")
bpy.ops.m3d.layer_mask_add(fill='WHITE')
check(layer.paint_mask and not mc_list() and slot_image(m) == LY.paint_effect(layer).image,
      "Add Mask: strokes go to the mask alone, no list (%s)" % mc_list())
check(bpy.ops.m3d.layer_paint_mask() == {'FINISHED'} and not layer.paint_mask and len(mc_list()) == 2,
      "...Paint Mask off: the list comes back with the channels (%s)" % mc_list())
layer.paint_mask = True
check(not mc_list(), "...and on again: no list")
layer.paint_mask = False
check(bpy.ops.m3d.layer_add(kind='FILL') == {'FINISHED'} and not mc_list() and slot_image(m).name == LY.SCRATCH,
      "a fill layer: the strokes go to the scratch image, no list")
check(bpy.ops.m3d.layer_folder_add() == {'FINISHED'} and not mc_list(), "a folder: no list")
m.m3d_layer_index = 0
check(len(mc_list()) == 2, "back on the paint layer: the list is back")

# New images take the size of the layer's other images, not the size of new slots.
mc_reset()
o, m = fresh_cube("MultiSize", '64')
bpy.ops.m3d.layer_add(kind='PAINT')
layer = m.m3d_layers[0]
small_ = bpy.data.images.new("MultiSize32", 32, 32, alpha=True)
LY.set_channel_space(small_, LY.CHANNEL_BY_ID['BASE_COLOR'])
with LY.muted():
    old_ = LY.entry_of(layer, 'BASE_COLOR').image
    LY.entry_of(layer, 'BASE_COLOR').image = small_
    bpy.data.images.remove(old_)
LY.rebuild_all(m)
mc_brush.use_roughness = mc_brush.use_metallic = True
check(all(tuple(LY.entry_of(layer, c).image.size) == (32, 32) for c in ('ROUGHNESS', 'METALLIC')),
      "new channel images have the size of the layer's other images (%s)" % [tuple(LY.entry_of(layer, c).image.size) for c in ('ROUGHNESS', 'METALLIC')])
check(LY.layer_size(bpy.context, layer) == (32, 32), "(layer_size)")

# Undo, Redo and File > Open bring back layers, not the window manager's property: the handlers write the list again.
for handler in (LY.undo_post, LY.load_post):
    del mc_wm[LY.TARGETS]
    handler()
    check(len(mc_list()) == 3, "%s writes the list again (%s)" % (handler.__name__, mc_list()))
bpy.ops.object.mode_set(mode='OBJECT')
clean_scene()
LY.undo_post()
check(not mc_list(), "without a mesh the list is empty")

# The Material section of Properties - Paint and the toggles of the context toolbar.
mc_reset()
o, m = fresh_cube("MultiUI", '64')
mc_ctx = TCtx('PROPS')
check("PROPERTIES_PT_m3d_tx_pp_material" not in tex_shown("tex_props") and T.no_project(mc_ctx), "no project: Properties waits for it (the start card)")
log = draw_stub(T.PROPERTIES_PT_m3d_tx_pp_material, mc_ctx)
check_calls("Material section, no layer", log)
check(not [r for r in log if r._kind == "prop"] and any(r._kind == "label" for r in log), "...with no layer: a message, no buttons")
bpy.ops.m3d.layer_add(kind='PAINT')
mc_brush.use_roughness = mc_brush.use_emission = True
log = draw_stub(T.PROPERTIES_PT_m3d_tx_pp_material, mc_ctx)
check_calls("Material section", log)
drawn_ = [r._args[1] for r in log if r._kind == "prop"]
check(drawn_[:5] == ["use_base_color", "use_height", "use_roughness", "use_metallic", "use_emission"]
      and "roughness" in drawn_ and "emission" in drawn_ and "metallic" not in drawn_ and "height" not in drawn_,
      "the Material section: a toggle for each channel, then a value for each that is on: %s" % drawn_)
check([r._kw.get("text") for r in log if r._kind == "prop"][:5] == T.button_texts(mc_ctx, T.MATERIAL_BUTTONS)
      and set(T.button_texts(mc_ctx, T.MATERIAL_BUTTONS)) in ({"Base Color", "Height", "Roughness", "Metallic", "Emission"}, {"Color", "Height", "Rough", "Metal", "Emit"}),
      "...with the labels of the buttons, title case (%s)" % T.button_texts(mc_ctx, T.MATERIAL_BUTTONS))
check(T.button_texts(NS(region=NS(width=2000), preferences=bpy.context.preferences), T.MATERIAL_BUTTONS) == ["Base Color", "Height", "Roughness", "Metallic", "Emission"]
      and T.button_texts(NS(region=NS(width=200), preferences=bpy.context.preferences), T.MATERIAL_BUTTONS) == ["Color", "Height", "Rough", "Metal", "Emit"],
      "...the whole names when they fit, the short ones in a narrow editor")
m.m3d_off = "EMISSION"
log = draw_stub(T.PROPERTIES_PT_m3d_tx_pp_material, mc_ctx)
check("use_emission" not in [r._args[1] for r in log if r._kind == "prop"] and "emission" not in [r._args[1] for r in log if r._kind == "prop"],
      "...a channel the texture set does not have has no button (hidden, not greyed)")
m.m3d_off = ""
bpy.ops.m3d.layer_mask_add(fill='WHITE')
m.m3d_layers[0].paint_mask = True
check("PROPERTIES_PT_m3d_tx_pp_material" not in tex_shown("tex_props") and "PROPERTIES_PT_m3d_tx_pp_gray" in tex_shown("tex_props"),
      "Properties - Mask (painting the mask) has no Material section: it has the grays")
m.m3d_layers[0].paint_mask = False
bpy.ops.m3d.tex_tool(tool='PAINT')
log = []
T.draw_status_line(Rec(log), wide_)
check_calls("Texture context toolbar with a paint layer", log)
drawn_ = [r._args[1] for r in log if r._kind == "prop"]
MC_TOGGLES = ["use_base_color", "use_height", "use_roughness", "use_metallic", "use_emission"]
check(not [d for d in drawn_ if d in MC_TOGGLES], "the context toolbar has no channel toggles: they are in Properties > Material (%s)" % [d for d in drawn_ if d in MC_TOGGLES])
mc_reset()
bpy.ops.object.mode_set(mode='OBJECT')
clean_scene()

# ----------------------------------------------------------------------------------------------------
# Properties (phase 2): the sections of Paint, Fill, Mask and Folder, what each control is a property of, the alpha and stencil
# pickers, a fill layer's texture and UV transform (nodes, numpy, Cycles, Merge Down, Flatten, Export, Convert, the library), the
# context toolbar of each tool, the 2D view's frame. (The real window: gui_test.py.)
pp_alphas = tempfile.mkdtemp(prefix="m3d_alpha_props_")
S.alpha_dir = lambda create=False: pp_alphas
tex_ws.m3d_layout = 1
pp_scene = bpy.context.scene
pp_ctx = TCtx('PROPS')
pp_wide = TCtx('RIGHT')   # (a wide window: the toolbar with all its labels; the workspace is the current one)
pp_wide.region = NS(type='HEADER', width=2560)
PP = "PROPERTIES_PT_m3d_tx_"


def pp_sections():
    """The Properties sections drawn now, as the last part of the class names."""
    return {n[len(PP):] for n in tex_shown("tex_props")}


def pp_draw(name, label=None):
    """Draw one section with the recording layout; the calls are checked. -> the log"""
    log = draw_stub(getattr(T, PP + name), pp_ctx)
    check_calls(label or "Properties " + name, log)
    return log


def pp_props(log):
    return [(r._args[1], r._args[0]) for r in log if r._kind == "prop"]


o, m = fresh_cube("PropsCube", '64')
mc_reset()
check(bpy.ops.m3d.layer_add(kind='PAINT') == {'FINISHED'}, "(a paint layer for the Properties tests)")
ipaint = bpy.context.tool_settings.image_paint
ups = ipaint.unified_paint_settings
bpy.ops.m3d.tex_tool(tool='PAINT')
T.image_brush(bpy.context).mask_texture = None   # (the brush asset keeps what earlier tests gave it)
T.image_brush(bpy.context).texture = None

# --- Properties - Paint: the sections of each tool (Advanced and Cursor are behind More Settings: the button is the last section)
PAINT_TOOL_SECTIONS = {
    'PAINT': {"pp_preview", "pp_brush", "pp_alpha", "pp_stencil", "pp_material", "pp_advanced", "pp_cursor", "pp_more"},
    'ERASER': {"pp_preview", "pp_brush", "pp_alpha", "pp_stencil", "pp_material", "pp_advanced", "pp_cursor", "pp_more"},
    'PROJECTION': {"pp_preview", "pp_projection", "pp_brush", "pp_material", "pp_advanced", "pp_cursor", "pp_more"},
    'POLYFILL': {"pp_preview", "pp_polyfill", "pp_material"},
    'SMUDGE': {"pp_preview", "pp_brush", "pp_advanced", "pp_cursor", "pp_more"},
    'CLONE': {"pp_preview", "pp_brush", "pp_clone", "pp_advanced", "pp_cursor", "pp_more"},
}
bpy.context.scene.m3d_tex.props_more = False
check(bpy.ops.m3d.tex_tool(tool='PAINT') == {'FINISHED'} and pp_sections() == PAINT_TOOL_SECTIONS['PAINT'] - {"pp_advanced", "pp_cursor"} | {"layer_props"},
      "Properties - Paint hides Advanced and Cursor until More Settings: %s" % sorted(pp_sections()))
bpy.context.scene.m3d_tex.props_more = True
for tool, want in PAINT_TOOL_SECTIONS.items():
    check(bpy.ops.m3d.tex_tool(tool=tool) == {'FINISHED'}, "(tool %s)" % tool)
    got = pp_sections()
    check(T.props_context(pp_ctx) == 'PAINT' and got == want | {"layer_props"}, "Properties - Paint, %s: its sections %s (want %s and Layer Settings)" % (tool, sorted(got), sorted(want)))
    for name in sorted(got):
        try:
            pp_draw(name, "Properties - Paint, %s, %s" % (tool, name))
        except Exception as err:
            check(False, "Properties - Paint, %s, %s draws: %r" % (tool, name, err))
bpy.ops.m3d.tex_tool(tool='PAINT')
check(T.props_pages(pp_ctx) == {T.PAINT_PAGE, T.LAYER_PAGE}, "Paint draws the paint page and the layer's settings")
order = sorted((c for c in T.classes if getattr(c, "page", "") == T.PAINT_PAGE), key=lambda c: c.bl_order)
check([c.__name__[len(PP):] for c in order if c.__name__[len(PP):] in PAINT_TOOL_SECTIONS['PAINT']] ==
      ["pp_preview", "pp_brush", "pp_alpha", "pp_stencil", "pp_material", "pp_advanced", "pp_cursor", "pp_more"],
      "the sections come in the order: previews, Brush, Alpha, Stencil, Material, then Advanced and Cursor, then the More Settings button")
closed = {c.__name__[len(PP):] for c in T.classes if getattr(c, "page", "") == T.PAINT_PAGE and 'DEFAULT_CLOSED' in getattr(c, "bl_options", ())}
check(closed == {"pp_brush", "pp_stencil", "pp_advanced", "pp_cursor", "pp_clone"}, "Brush, Stencil, Advanced and Cursor start closed (Alpha and Material open): %s" % sorted(closed))
pp_orders = {c.__name__[len(PP):]: c.bl_order for c in order}
check(pp_orders["pp_projection"] < pp_orders["pp_brush"] and pp_orders["pp_polyfill"] < pp_orders["pp_material"], "the Projection tool's stencil and Polygon Fill's mode come before the rest")

# --- Previews: the brush and the material swatches
mc_brush.use_roughness = mc_brush.use_emission = True
mc_brush.roughness, mc_brush.height = 0.25, 0.75
log = pp_draw("pp_preview")
check([n for n, _o in pp_props(log)] == ["color", "swatch_roughness", "emission"],
      "the swatches of the channels that are on: color, the grey of Roughness, emission: %s" % [n for n, _o in pp_props(log)])
check([t for t in (r._kw.get("text") for r in log if r._kind == "label") if t in {c.label for c in T.CHANNELS}] == ["Base Color", "Roughness", "Emission"],
      "...each with the channel's name")
check(all(abs(a - 0.25) < 1e-6 for a in mc_brush.swatch_roughness) and all(abs(a - 0.75) < 1e-6 for a in mc_brush.swatch_height)
      and all(mc_brush.bl_rna.properties["swatch_" + c].is_readonly for c in ("height", "roughness", "metallic")), "a swatch is the value as a grey, read only")
check((any(r._kind == "template_icon" and r._kw.get("icon_value") for r in log) or any(r._kind == "label" and r._kw.get("icon") == 'BRUSH_DATA' for r in log))
      and any(r._kind == "label" and r._kw.get("text") == T.brush_name(bpy.context) for r in log),
      "the brush is shown with its thumbnail (a brush icon without one, as here in the background) and name")
bpy.ops.m3d.tex_tool(tool='SMUDGE')
check(not [r for r in pp_draw("pp_preview") if r._kind == "prop"], "Smudge paints one channel: no swatches")
bpy.ops.m3d.tex_tool(tool='PAINT')
mc_reset()

# --- Brush: each control is a property of the brush, the unified settings, the alpha slot or the Project Paint settings
brush = T.image_brush(bpy.context)
ups.use_unified_size = ups.use_unified_strength = True
log = pp_draw("pp_brush")
drawn = {n: owner for n, owner in reversed(pp_props(log))}
texts = {r._args[1]: r._kw.get("text") for r in log if r._kind == "prop"}
check(drawn["size"] == ups and drawn["strength"] == ups and texts["size"] == "Size" and texts["strength"] == "Flow",
      "Size and Flow (the brush strength) are the unified settings when those are on")
for name, owner in (("use_pressure_size", brush), ("use_pressure_strength", brush), ("hardness", brush), ("spacing", brush),
                    ("use_pressure_spacing", brush), ("use_locked_size", ups), ("jitter", brush), ("use_pressure_jitter", brush),
                    ("use_occlude", ipaint), ("use_backface_culling", ipaint), ("use_normal_falloff", ipaint), ("normal_angle", ipaint)):
    check(name in drawn and drawn[name] == owner, "Brush draws %s on the right owner" % name)
check(texts["jitter"] == "Position Jitter" and texts["use_backface_culling"] == "Backface Culling" and texts["use_locked_size"] == "Size Space",
      "...with the names of the reference")
if brush.image_paint_capabilities.has_accumulate:
    check(drawn.get("use_accumulate") == brush, "Accumulate: whether a stroke may go past its Flow (Blender's Stroke Opacity)")
check(not {"angle", "use_rake", "use_random"} & set(drawn), "no alpha: no Angle, Follow Path or Angle Jitter (%s)" % sorted(drawn))
check(not [n for n in drawn if "flow" in n or ("jitter" in n and n not in {"jitter", "use_pressure_jitter"})], "Size, Flow and Angle jitter that Blender has no property for are not faked")
ups.use_unified_size = ups.use_unified_strength = False
drawn = {n: owner for n, owner in reversed(pp_props(pp_draw("pp_brush")))}
check(drawn["size"] == brush and drawn["strength"] == brush, "...the brush's own when they are off")
ups.use_unified_size = ups.use_unified_strength = True
ups.use_locked_size = 'SCENE'
drawn = {n: owner for n, owner in reversed(pp_props(pp_draw("pp_brush")))}
check("unprojected_size" in drawn and "size" not in drawn, "Size Space Scene: the size in scene units")
ups.use_locked_size = 'VIEW'

# --- Alpha: the library, the brush's Texture Mask, its mapping
check(bpy.ops.m3d.alpha_pick(name="Dots") == {'FINISHED'} and brush.mask_texture is not None and brush.mask_texture.name == "Dots"
      and brush.mask_texture_slot.mask_map_mode == 'VIEW_PLANE', "a tile of the Alpha section gives the brush that alpha (its Texture Mask, Camera mapping)")
log = pp_draw("pp_alpha")
picks = [r for r in log if r._kind == "operator" and r._args[0] == "m3d.alpha_pick"]
names = ["", *S.alpha_names()]
check([r.values()["name"] for r in picks][-len(names):] == names and not any(r.values()["stencil"] for r in picks)
      and [r.values()["name"] for r in picks if r._kw.get("depress")] == ["Dots"], "the grid: None and every alpha of the library, the alpha in use pressed")
check([r._args[2] for r in log if r._kind == "prop_enum"] == ['VIEW_PLANE', 'TILED', 'RANDOM', 'STENCIL']
      and all(r._args[0] == brush.mask_texture_slot and r._args[1] == "mask_map_mode" for r in log if r._kind == "prop_enum")
      and [r._kw["text"] for r in log if r._kind == "prop_enum"][0] == "Camera", "Alignment: Camera (View Plane), Tiled, Random, Stencil on the alpha's slot")
check(any(r._kind == "operator" and r._args[0] == "m3d.alpha_load" and not r.values()["stencil"] for r in log), "Load Alpha... is there")
slot = brush.mask_texture_slot
check(slot.has_texture_angle, "(an alpha in View Plane mapping has an angle)")
drawn = {n: owner for n, owner in reversed(pp_props(pp_draw("pp_brush")))}
check(drawn.get("angle") == slot and drawn.get("use_rake") == slot, "with an alpha the Brush section has its Angle and Follow Path (Rake)")
if slot.has_texture_angle_source and brush.brush_capabilities.has_random_texture_angle:
    check(drawn.get("use_random") == slot, "...and Angle Jitter (Random)")
check(bpy.ops.m3d.alpha_pick(name="") == {'FINISHED'} and brush.mask_texture is None, "None takes the alpha off")
check(not [r for r in pp_draw("pp_alpha") if r._kind == "prop_enum"], "no alpha: no Alignment")

# --- Stencil: the brush's Texture mapped in screen space
log = pp_draw("pp_stencil")
ops = [r._args[0] for r in log if r._kind == "operator"]
check(ops[:3] == ["m3d.tex_stencil", "brush.stencil_reset_transform", "brush.stencil_fit_image_aspect"] and "m3d.alpha_load" in ops
      and "texture_overlay_alpha" in [n for n, _o in pp_props(log)], "the Stencil section: the S button, Reset, Fit, the opacity, the library, Load Stencil")
check(all(r.values()["stencil"] for r in log if r._kind == "operator" and r._args[0] in {"m3d.alpha_pick", "m3d.alpha_load"}), "...its tiles and Load Stencil make a stencil, not an alpha")
check(bpy.ops.m3d.alpha_pick(name="Clouds", stencil=True) == {'FINISHED'} and brush.texture.name == "Clouds" and brush.texture_slot.map_mode == 'STENCIL'
      and brush.mask_texture is None and T.tool_of(bpy.context) == 'PROJECTION', "a stencil tile maps the texture as a Stencil: the Projection tool")
check([r.values()["name"] for r in pp_draw("pp_stencil") if r._kind == "operator" and r._args[0] == "m3d.alpha_pick" and r._kw.get("depress")] == ["Clouds"],
      "...the tile in use is pressed")
check(bpy.ops.m3d.alpha_pick(name="Stripes", stencil=True) == {'FINISHED'} and brush.texture.name == "Stripes" and T.stencil_on(brush), "another one replaces it")
check(bpy.ops.m3d.alpha_pick(name="", stencil=True) == {'FINISHED'} and not T.stencil_on(brush) and brush.texture is None and T.tool_of(bpy.context) == 'PAINT',
      "None takes the stencil off (and the texture it brought)")
pp_png = bpy.data.images.new("ppStencilFile", 8, 8)
pp_png.filepath_raw, pp_png.file_format = os.path.join(pp_alphas, "ppStencilFile.png"), 'PNG'
pp_png.save()
check(bpy.ops.m3d.alpha_load(filepath=pp_png.filepath_raw, stencil=True) == {'FINISHED'} and brush.texture is not None and brush.texture.name == "ppStencilFile"
      and T.stencil_on(brush), "Load Stencil adds the file to the library and makes it the stencil")
bpy.ops.m3d.tex_tool(tool='PAINT')
check(not T.stencil_on(brush) and brush.texture is None, "another tool takes the stencil off")
bpy.ops.m3d.tex_tool(tool='PROJECTION')
log = pp_draw("pp_projection")
check([r._args[0] for r in log if r._kind == "operator"][:1] == ["m3d.tex_stencil"], "the Projection tool shows the stencil section")
bpy.ops.m3d.tex_tool(tool='PAINT')

# --- Material: the toggles (the Eraser: only those), Polygon Fill's mode, the grays of a mask
mc_brush.use_roughness = True
TOGGLES = ["use_base_color", "use_height", "use_roughness", "use_metallic", "use_emission"]
bpy.ops.m3d.tex_tool(tool='ERASER')
check([n for n, _o in pp_props(pp_draw("pp_material"))] == TOGGLES, "the Eraser's Material has the toggles only")
bpy.ops.m3d.tex_tool(tool='PAINT')
check([n for n, _o in pp_props(pp_draw("pp_material"))] == TOGGLES + ["color", "roughness"], "Paint's Material has the toggles and a value for each channel that is on")
bpy.ops.m3d.tex_tool(tool='POLYFILL')
check(("fill_mode", pp_scene.m3d_tex) in pp_props(pp_draw("pp_polyfill")), "Polygon Fill has its mode (polygon, UV island, mesh)")
check({"fill_mode"} == {n for n, _o in pp_props(pp_draw("pp_polyfill"))}, "...and Triangle is not offered: a mask can only select whole polygons")
bpy.ops.m3d.tex_tool(tool='CLONE')
check(any(r._kind == "template_list" and r._args[0] == "TEXTURE_UL_texpaintslots" for r in pp_draw("pp_clone")), "Clone has its source section: the slot to clone from")
bpy.ops.m3d.tex_tool(tool='PAINT')
mc_reset()

# --- Properties - Fill
check(bpy.ops.m3d.layer_add(kind='FILL') == {'FINISHED'}, "(a fill layer)")
fill = LY.active_layer(m)
check(T.props_context(pp_ctx) == 'FILL' and pp_sections() == {"fl_fill", "fl_material", "layer_props"} and T.props_pages(pp_ctx) == {T.FILL_PAGE, T.LAYER_PAGE},
      "Properties - Fill: Fill, Material and Layer Settings (%s)" % sorted(pp_sections()))
log = pp_draw("layer_props")
check({"name", "blend", "opacity", "visible"} <= {n for n, _o in pp_props(log)} and "color" not in {n for n, _o in pp_props(log)},
      "...Layer Settings: name, every channel's blend and opacity, visible (the values are in Material)")
log = pp_draw("fl_fill")
check([(n, o == fill) for n, o in pp_props(log)] == [("projection", True), ("uv_tiling", True), ("uv_rotation", True), ("uv_offset", True)]
      and [r._args[0] for r in log if r._kind == "operator"] == ["m3d.layer_fill_reset"],
      "Fill: the projection, the UV transform of the layer (Tiling, Rotation, Offset) and Reset")
log = pp_draw("fl_material")
uses = [(r._args[1], r._kw.get("text")) for r in log if r._kind == "prop" and r._args[1] == "use"]
check(uses == [("use", t) for t in T.button_texts(bpy.context, T.FILL_BUTTONS)] and T.FILL_BUTTONS[-1][1] == "Normal"
      and [r._args[0] for r in log if r._kind == "prop" and r._args[1] == "use"] == [LY.entry_of(fill, c) for c in ("BASE_COLOR", "HEIGHT", "ROUGHNESS", "METALLIC", "EMISSION", "NORMAL")],
      "Material: a button for each channel of a fill layer (Base Color Height Roughness Metallic Emission Normal)")
check([(r._args[1], r._args[0] == LY.entry_of(fill, 'BASE_COLOR')) for r in log if r._kind == "prop" and r._args[1] != "use"] == [("color", True)]
      and [(r._args[1], r._args[0] == LY.entry_of(fill, 'BASE_COLOR')) for r in log if r._kind == "template_ID"] == [("texture", True)],
      "...a color and a texture slot for each channel that is on")
for cid in ('ROUGHNESS', 'NORMAL'):
    LY.entry_of(fill, cid).use = True
log = pp_draw("fl_material")
check([r._args[1] for r in log if r._kind == "prop" and r._args[1] != "use"] == ["color", "value"] and len([r for r in log if r._kind == "template_ID"]) == 3,
      "...a number for Roughness, nothing but the texture for Normal (a flat Normal has no value)")

# --- A fill layer's texture and UV transform: the node chain
tex_a = bpy.data.images.new("ppTexA", 4, 4, alpha=True, is_data=True)   # distinct grays, a ramp of 16 steps
ramp_px = np.zeros((4, 4, 4), np.float32)
ramp_px[..., :3] = (np.arange(16, dtype=np.float32).reshape(4, 4) / 15.0)[..., None]
ramp_px[..., 3] = 1.0
LY.write_pixels(tex_a, ramp_px)
pp_rough = LY.entry_of(fill, 'ROUGHNESS')
nodes_before = {n.name for n in m.node_tree.nodes}
pp_rough.texture = tex_a
nodes_after = {n.name for n in m.node_tree.nodes}
tex_name, map_name, coord_name = (LY.part('ROUGHNESS', fill.uid, k) for k in ("tex", "map", "coord"))
check(nodes_after - nodes_before == {tex_name, map_name, coord_name}, "a fill's texture adds an Image Texture, a Mapping and a Texture Coordinate node: %s" % sorted(nodes_after ^ nodes_before))
tex_node, map_node, coord_node = (m.node_tree.nodes[n] for n in (tex_name, map_name, coord_name))
check(tex_node.image == tex_a and any(l.from_node == coord_node and l.from_socket.name == "UV" for l in map_node.inputs["Vector"].links)
      and any(l.from_node == map_node for l in tex_node.inputs["Vector"].links), "UV -> Mapping -> the texture")
check(any(l.from_node == tex_node for l in m.node_tree.nodes[LY.part('ROUGHNESS', fill.uid, "mix")].inputs[7].links)
      and not m.node_tree.nodes.get(LY.part('ROUGHNESS', fill.uid, "fill")), "...and the texture feeds the layer's Mix instead of the value")
check(abs(m.node_tree.nodes[LY.part('ROUGHNESS', fill.uid, "opv")].inputs[0].default_value - 1.0) < 1e-6 and not m.node_tree.nodes[LY.part('ROUGHNESS', fill.uid, "opv")].inputs[0].links,
      "the texture's alpha is not used: the fill covers everything")
check(tuple(map_node.inputs["Scale"].default_value) == (1.0, 1.0, 1.0) and tuple(map_node.inputs["Rotation"].default_value) == (0.0, 0.0, 0.0)
      and all(abs(a) < 1e-6 for a in map_node.inputs["Location"].default_value), "the start transform is the identity")
fill.uv_tiling, fill.uv_rotation, fill.uv_offset = (2.0, 3.0), 0.5, (0.1, -0.2)
want_loc, want_rot, want_scale = LY.fill_mapping(fill)
check(tuple(round(v, 5) for v in map_node.inputs["Scale"].default_value) == (2.0, 3.0, 1.0) and abs(map_node.inputs["Rotation"].default_value[2] - 0.5) < 1e-6
      and all(abs(a - b) < 1e-5 for a, b in zip(map_node.inputs["Location"].default_value, want_loc))
      and {n.name for n in m.node_tree.nodes} == nodes_after, "Tiling, Rotation and Offset set the Mapping node's values (no node is made again)")
check(all(abs(a - b) < 1e-6 for a, b in zip(want_loc, (0.5 - (2 * 0.5 * np.cos(0.5) - 3 * 0.5 * np.sin(0.5)) + 0.1, 0.5 - (2 * 0.5 * np.sin(0.5) + 3 * 0.5 * np.cos(0.5)) - 0.2, 0.0))),
      "(the tiling and the rotation turn around the middle of the UV map: the location is worked out by hand)")
check(bpy.ops.m3d.layer_fill_reset() == {'FINISHED'} and tuple(fill.uv_tiling) == (1.0, 1.0) and fill.uv_rotation == 0.0 and tuple(fill.uv_offset) == (0.0, 0.0),
      "Reset puts the transform back")
check(tex_node.name in m.node_tree.nodes and m.node_tree.nodes[tex_name].image == tex_a, "...the texture stays")
pp_rough.texture = None
check(not {n for n in (tex_name, map_name, coord_name) if n in m.node_tree.nodes} and not m.node_tree.nodes[LY.part('ROUGHNESS', fill.uid, "mix")].inputs[7].links,
      "no texture: the three nodes go and the value is back")
check(abs(m.node_tree.nodes[LY.part('ROUGHNESS', fill.uid, "mix")].inputs[7].default_value[0] - pp_rough.value) < 1e-6, "...as the Mix node's color")
for cid in ('ROUGHNESS', 'NORMAL'):
    LY.entry_of(fill, cid).use = False

# --- ...in a folder (a fill is then a color node or a texture), and the color space a picked file takes
bpy.ops.m3d.layer_folder_add(group=True)
pp_rough.use = True
pp_rough.texture = tex_a
check(m.node_tree.nodes.get(LY.part('ROUGHNESS', fill.uid, "tex")) is not None and m.node_tree.nodes.get(LY.part('ROUGHNESS', fill.uid, "map")) is not None
      and m.node_tree.nodes.get(LY.part('ROUGHNESS', fill.uid, "fill")) is None, "a fill layer in a folder has the texture nodes too")
pp_rough.texture = None
check(m.node_tree.nodes.get(LY.part('ROUGHNESS', fill.uid, "fill")) is not None and m.node_tree.nodes.get(LY.part('ROUGHNESS', fill.uid, "tex")) is None,
      "...and the color node when the texture goes")
pp_rough.use = False
LY.activate(m, fill.uid)
pp_file = bpy.data.images.new("ppColorFile", 4, 4)
pp_file.filepath_raw, pp_file.file_format = os.path.join(pp_alphas, "ppColorFile.png"), 'PNG'
pp_file.save()
pp_loaded = bpy.data.images.load(pp_file.filepath_raw)
pp_loaded.colorspace_settings.name = 'sRGB'
LY.entry_of(fill, 'ROUGHNESS').use = True
LY.entry_of(fill, 'ROUGHNESS').texture = pp_loaded
check(pp_loaded.colorspace_settings.name == 'Non-Color' and pp_loaded.get(LY.FILL_TEXTURE) == 'ROUGHNESS', "a file picked for Roughness is Non-Color")
LY.entry_of(fill, 'BASE_COLOR').texture = pp_loaded
check(pp_loaded.colorspace_settings.name == 'Non-Color', "...the first channel an image is used for decides")
LY.entry_of(fill, 'BASE_COLOR').texture = None
LY.entry_of(fill, 'ROUGHNESS').texture = None
LY.entry_of(fill, 'ROUGHNESS').use = False
pp_file2 = bpy.data.images.new("ppGenerated", 4, 4)
LY.entry_of(fill, 'BASE_COLOR').texture = pp_file2
check(pp_file2.colorspace_settings.name != 'Non-Color' and LY.FILL_TEXTURE not in pp_file2.keys(), "a generated image keeps its color space (choosing it again would blank the pixels)")
LY.entry_of(fill, 'BASE_COLOR').texture = None

# --- ...numpy: Flatten, Merge Down and Export see the texture as the nodes do (UV: nearest and linear, tiling, rotation, offset)
pp_cube, pp_mat = fresh_cube("PropsFlat", '64')
bpy.ops.m3d.layer_add(kind='PAINT')
pp_base = LY.active_layer(pp_mat)
pp_auto = LY.entry_of(pp_base, 'BASE_COLOR')   # (a new paint layer gets the Base Color image the brush aims at: this stack is 8 px, Roughness only)
pp_auto_image = pp_auto.image
with LY.muted():
    pp_auto.image, pp_auto.use = None, False
bpy.data.images.remove(pp_auto_image)
bpy.ops.m3d.layer_add(kind='FILL')
pp_fill = LY.active_layer(pp_mat)
tex_b = bpy.data.images.new("ppTexB", 4, 4, alpha=False, is_data=True)
LY.write_pixels(tex_b, ramp_px)
with LY.muted():
    LY.entry_of(pp_base, 'ROUGHNESS').use = True
    LY.entry_of(pp_base, 'ROUGHNESS').image = LY.make_channel_image(pp_mat, pp_base, LY.CHANNEL_BY_ID['ROUGHNESS'], 8, opaque=True)
    LY.set_look(pp_fill, blend='MIX', opacity=1.0)
    LY.entry_of(pp_fill, 'ROUGHNESS').use = True
    LY.entry_of(pp_fill, 'ROUGHNESS').texture = tex_b
LY.rebuild_all(pp_mat)
flat = LY.flatten_channel(pp_mat, 'ROUGHNESS', 4)[..., 0]
check(np.abs(flat - ramp_px[..., 0]).max() < 1e-5, "Tiling 1, Rotation 0, Offset 0: the flattened channel is the texture itself (%.1e)" % np.abs(flat - ramp_px[..., 0]).max())
pp_fill.uv_tiling = (2.0, 2.0)
tex_node = pp_mat.node_tree.nodes[LY.part('ROUGHNESS', pp_fill.uid, "tex")]
tex_node.interpolation = 'Closest'
flat = LY.flatten_channel(pp_mat, 'ROUGHNESS', 8)[..., 0]
# worked out by hand: Tiling 2 grows from the middle of the UV map, texel (x, y) of the 8 x 8 result reads texel (x - 2, y - 2) of the 4 x 4 texture, repeating
want = np.array([[ramp_px[(y - 2) % 4, (x - 2) % 4, 0] for x in range(8)] for y in range(8)])
check(np.abs(flat - want).max() < 1e-5, "Tiling 2 (nearest): the texture repeats twice around the middle (%.1e)" % np.abs(flat - want).max())
pp_fill.uv_tiling, pp_fill.uv_offset = (1.0, 1.0), (0.25, 0.0)
flat = LY.flatten_channel(pp_mat, 'ROUGHNESS', 4)[..., 0]
want = np.array([[ramp_px[y, (x + 1) % 4, 0] for x in range(4)] for y in range(4)])   # (Offset 0.25: the texture is read one texel to the right)
check(np.abs(flat - want).max() < 1e-5, "Offset 0.25 (nearest): read one texel further (%.1e)" % np.abs(flat - want).max())
pp_fill.uv_offset = (0.0, 0.0)
pp_fill.uv_rotation = np.pi / 2
flat = LY.flatten_channel(pp_mat, 'ROUGHNESS', 4)[..., 0]
want = np.array([[ramp_px[x, 3 - y, 0] for x in range(4)] for y in range(4)])   # (a quarter turn about the middle: (u, v) is read at (1 - v, u))
check(np.abs(flat - want).max() < 1e-5, "Rotation 90 degrees (nearest): a quarter turn about the middle (%.1e)" % np.abs(flat - want).max())
pp_fill.uv_rotation = 0.0
tex_node.interpolation = 'Linear'
pp_fill.uv_offset = (0.125, 0.0)
flat = LY.flatten_channel(pp_mat, 'ROUGHNESS', 4)[..., 0]
want = np.array([[0.5 * ramp_px[y, x, 0] + 0.5 * ramp_px[y, (x + 1) % 4, 0] for x in range(4)] for y in range(4)])   # (half a texel: halfway between two neighbours)
check(np.abs(flat - want).max() < 1e-5, "Offset 0.125 (linear): halfway between two texels, wrapping (%.1e)" % np.abs(flat - want).max())
pp_fill.uv_offset = (0.0, 0.0)

# the same through Merge Down, Flatten and Export
pp_fill.uv_tiling, pp_fill.uv_rotation, pp_fill.uv_offset = (1.5, 2.0), 0.7, (0.1, -0.2)
LY.set_look(pp_fill, opacity=0.6)
LY.rebuild_all(pp_mat)
tex_node.interpolation = 'Closest'
base_img = LY.entry_of(pp_base, 'ROUGHNESS').image
LY.write_pixels(base_img, np.full((8, 8, 4), (0.3, 0.3, 0.3, 1.0), np.float32))
want = LY.flatten_channel(pp_mat, 'ROUGHNESS', 8)[..., 0].copy()
direct = LY.fill_planes(pp_fill, LY.CHANNEL_BY_ID['ROUGHNESS'], 8)[..., 0]
pp_stored = LY.pixels_of(base_img, 8)[..., 0]   # (8 bit: 0.3 is stored as 77 / 255)
check(np.abs(want - (pp_stored + 0.6 * (direct - pp_stored))).max() < 1e-5, "(the flattened channel is the texture over the base at the layer's opacity)")
pp_mat.m3d_layer_index = LY.index_of(pp_mat, pp_fill.uid)
check(bpy.ops.m3d.layer_merge_down() == {'FINISHED'} and len(pp_mat.m3d_layers) == 1, "Merge Down of a textured fill runs")
got = read(LY.entry_of(pp_mat.m3d_layers[0], 'ROUGHNESS').image).reshape(8, 8, 4)[..., 0]
check(np.abs(got - want).max() <= 1.5 / 255, "...and the merged layer is the flattened result (%.4f)" % np.abs(got - want).max())

pp_cube2, pp_mat2 = fresh_cube("PropsExport", '64')
bpy.ops.m3d.layer_add(kind='PAINT')
pp_base2 = LY.active_layer(pp_mat2)
with LY.muted():
    LY.entry_of(pp_base2, 'BASE_COLOR').use = True
    LY.entry_of(pp_base2, 'BASE_COLOR').image = LY.make_channel_image(pp_mat2, pp_base2, LY.CHANNEL_BY_ID['BASE_COLOR'], 8, opaque=True)
bpy.ops.m3d.layer_add(kind='FILL')
pp_fill2 = LY.active_layer(pp_mat2)
tex_c = bpy.data.images.new("ppTexC", 4, 4, alpha=False)
col_px = np.zeros((4, 4, 4), np.float32)
col_px[..., 0] = np.linspace(0.1, 0.9, 4)[None, :]
col_px[..., 1] = np.linspace(0.2, 0.7, 4)[:, None]
col_px[..., 2], col_px[..., 3] = 0.4, 1.0
LY.set_channel_space(tex_c, LY.CHANNEL_BY_ID['BASE_COLOR'])
LY.write_pixels(tex_c, col_px)
with LY.muted():
    LY.entry_of(pp_fill2, 'BASE_COLOR').texture = tex_c
    pp_fill2.uv_tiling = (2.0, 2.0)
    LY.set_look(pp_fill2, blend='MULTIPLY', opacity=0.5)
LY.rebuild_all(pp_mat2)
LY.write_pixels(LY.entry_of(pp_base2, 'BASE_COLOR').image, np.full((8, 8, 4), (0.6, 0.5, 0.4, 1.0), np.float32))
pp_mat2.node_tree.nodes[LY.part('BASE_COLOR', pp_fill2.uid, "tex")].interpolation = 'Closest'
pp_dir = tempfile.mkdtemp(prefix="m3d_export_props_")
pp_tx = bpy.context.scene.m3d_tex
pp_tx.export_folder, pp_tx.export_size, pp_tx.export_preset = pp_dir, 'SAME', 'UNREAL'
pp_tx.export_padding = 'NONE'   # (the files are compared with the flattened stack: no padding)
pp_state = sorted(n.name for n in pp_mat2.node_tree.nodes)
check(bpy.ops.m3d.tex_export() == {'FINISHED'}, "Unreal export of a stack with a textured fill runs")
bc, _img = load_png(pp_dir, "T_PropsExport_BC.png")
want_bc = LY.flatten_channel(pp_mat2, 'BASE_COLOR', 8).reshape(-1, 4)
check(np.abs(bc[:, :3] - want_bc[:, :3]).max() < 2.5 / 255 and sorted(n.name for n in pp_mat2.node_tree.nodes) == pp_state,
      "the exported base color is the flattened stack, texture and all (%.4f); the nodes are untouched" % np.abs(bc[:, :3] - want_bc[:, :3]).max())
check(np.abs(want_bc[:, :3] - bc[:, :3]).max() < 2.5 / 255 and bc[:, 0].std() > 0.01, "...it is not flat")

# --- Convert to Paint, Duplicate and the library keep the texture
pp_conv = LY.active_layer(pp_mat2)
bpy.ops.m3d.layer_duplicate()
pp_dup = LY.active_layer(pp_mat2)
check(LY.entry_of(pp_dup, 'BASE_COLOR').texture == tex_c and tuple(pp_dup.uv_tiling) == (2.0, 2.0) and pp_dup.uid != pp_conv.uid,
      "Duplicate copies the texture (the same image) and the transform")
want_conv = LY.fill_planes(pp_dup, LY.CHANNEL_BY_ID['BASE_COLOR'], 64)
check(bpy.ops.m3d.layer_convert() == {'FINISHED'} and pp_dup.kind == 'PAINT' and LY.entry_of(pp_dup, 'BASE_COLOR').texture is None
      and np.abs(LY.pixels_of(LY.entry_of(pp_dup, 'BASE_COLOR').image, 64)[..., :3] - LY.to_srgb(want_conv)).max() < 1.5 / 255,
      "Convert to Paint Layer paints the texture (as it looks) into the layer")
pp_lib_root, pp_lib_saved = tempfile.mkdtemp(prefix="m3d_lib_props_"), LIB.library_dir
LIB.library_dir = lambda create=False: pp_lib_root
LIB._user["entries"] = None
pp_mat2.m3d_layer_index = LY.index_of(pp_mat2, pp_fill2.uid)
pp_files = LIB.Files()
pp_spec = LIB.describe_layer(pp_fill2, pp_files)
check(pp_spec.get("textures") == {"BASE_COLOR": "image1.png"} and pp_spec["uv"]["tiling"] == [2.0, 2.0] and list(pp_files) == ["image1.png"],
      "Save to Library keeps a fill's textures and its UV transform: %s" % {k: pp_spec.get(k) for k in ("textures", "uv")})
pp_ref = LIB.save_user_item(LIB.describe_material("Textured Fill", pp_fill2, pp_files), pp_files)
before_layers, pp_fill2_uid = len(pp_mat2.m3d_layers), pp_fill2.uid   # (the uid is read before the layers are added: a collection that grows moves its items)
check(bpy.ops.m3d.library_apply(item=pp_ref) == {'FINISHED'} and len(pp_mat2.m3d_layers) == before_layers + 2, "the saved item applies")
pp_applied = next(l for l in pp_mat2.m3d_layers if l.kind == 'FILL' and l.uid != pp_fill2_uid and LY.has_texture(l, 'BASE_COLOR'))
check(tuple(pp_applied.uv_tiling) == (2.0, 2.0) and LY.entry_of(pp_applied, 'BASE_COLOR').texture is not None
      and np.abs(read(LY.entry_of(pp_applied, 'BASE_COLOR').texture).reshape(4, 4, 4)[..., :3] - col_px[..., :3]).max() < 1.5 / 255,
      "...with its texture (the pixels came back) and its transform")
LIB.library_dir = pp_lib_saved
LIB._user["entries"] = None
