def p4_export(preset, **settings):
    out = p4_dir()
    p4_tx.export_folder, p4_tx.export_preset = out, preset
    for k_, v_ in settings.items():
        setattr(p4_tx, k_, v_)
    res = bpy.ops.m3d.tex_export_dialog('EXEC_DEFAULT')
    return res, out, sorted(os.listdir(out))


