check("PROPERTIES_PT_m3d_tx_stack" in tex_shown("tex_layers") and "PROPERTIES_PT_m3d_tx_set_general" not in tex_shown("tex_layers"), "...the Layers panel is what the dock draws, not Texture Set Settings")
