check(("INFO", "Baked 2 groups") == bq_reports[-1][:2] or bq_reports[-1][1].startswith("Baked 2 groups"), "...and it says so: %s" % bq_reports)
check(QQ.progress()[0] == 0 and QQ.text() == "", "(no queue, no progress text)")

