log = []
T.draw_header_sets(Rec(log), TCtx('SETS'))
check(any(r._kind == "operator" and r._args[0] == "m3d.tex_isolate" for r in log), "with a project the Texture Sets header has Isolate")
check(T.START_EMPTY == {"tex_layers", "tex_settings", "tex_props"} and T.pages_new(TCtx('RIGHT'), "tex_layers") == {"tex_layers"},
      "...and the dock shows its page again")
ux_sp = NS(overlay=NS(show_floor=True, show_axis_x=True, show_axis_y=True, show_axis_z=False))
T.hide_floor(ux_sp)
check(not (ux_sp.overlay.show_floor or ux_sp.overlay.show_axis_x or ux_sp.overlay.show_axis_y or ux_sp.overlay.show_axis_z), "F4's 3D view: no floor grid, no axis lines")
ux_key = find("Image Paint", "m3d.tex_layout", 'SPACE', ctrl=True, shift=False, alt=False)
ux_key2 = find("Image", "m3d.tex_layout", 'SPACE', ctrl=True, shift=False, alt=False)
check(ux_key and ux_key[0].properties.mode == 'TOGGLE' and ux_key2 and ux_key2[0].properties.mode == 'TOGGLE',
      "Ctrl+Space in Texture Paint Mode and in the 2D view: the view under the pointer alone, or both views")
check(T.M3D_OT_tex_layout.invoke(NS(mode='TOGGLE', execute=lambda c: {'FINISHED'}), fb_ctx('VIEW_3D', fb_v3d, bpy.data.workspaces["Modeling"]), None) == {'PASS_THROUGH'},
      "...outside the Texture workspace it is Blender's maximize (the key passes through)")
bpy.ops.object.mode_set(mode='OBJECT')
clean_scene()

# --- Texture UX part 3: one selected thumbnail decides what strokes paint and what Properties shows; the mask controls
u3_ob, u3_mat = fresh_cube("Ux3", '64')
bpy.ops.m3d.layer_add(kind='FILL')
u3_fill = LY.active_layer(u3_mat)
check(LY.target_image(bpy.context, u3_mat, False) is None and T.paint_status(bpy.context, u3_mat, u3_fill) == "Fill Layer: add a mask to paint it",
      "a fill without a mask: nothing painted, the Layers panel says to add a mask")
log = draw_stub(T.PROPERTIES_PT_m3d_tx_stack, TCtx())
check(any(r._kind == "operator" and r._args[0] == "m3d.layer_convert" for r in log) and "Fill Layer: add a mask to paint it" in [r._kw.get("text") for r in log],
      "...with Convert to Paint Layer under it")
check(bpy.ops.m3d.mask_effect_add(kind='LEVELS') == {'FINISHED'} and u3_fill.paint_mask and LY.mask_active(u3_fill) and T.props_context(TCtx('PROPS')) == 'MASK',
      "a new effect of any kind selects the mask (Properties shows it)")
check(LY.target_image(bpy.context, u3_mat, False) is None and T.paint_status(bpy.context, u3_mat, u3_fill) == "The mask has no Paint effect: add one to paint it"
      and T.PAINT_PAGE not in T.props_pages(TCtx('PROPS')), "a mask without a Paint effect: nothing painted, no brush sections, a hint that says why")
check(bpy.ops.m3d.mask_effect_add(kind='PAINT', fill='BLACK') == {'FINISHED'} and LY.target_image(bpy.context, u3_mat, False) == LY.paint_effect(u3_fill).image
      and T.paint_status(bpy.context, u3_mat, u3_fill) == "Painting %s mask" % u3_fill.name, "a Paint effect: strokes paint it; one wording in Layers ...")
log = []
T.draw_effect(Rec(log), u3_fill, LY.paint_effect(u3_fill))
hints = [r._kw.get("text") for r in log if r._kind == "label" and r._kw.get("icon") == 'INFO']
check(hints == ["Painting %s mask" % u3_fill.name], "...and in Properties (no 'Turn on Paint Mask' while the mask is painted): %s" % hints)
u3_fill.paint_mask = False
log = []
T.draw_effect(Rec(log), u3_fill, LY.paint_effect(u3_fill))
check([r._kw.get("text") for r in log if r._kind == "label" and r._kw.get("icon") == 'INFO'] == ["Click the mask thumbnail to paint it"],
      "the content selected: the effect says how to paint it")
u3_fill.paint_mask = True
# the Mask section: Use Mask, Show Mask, Invert and the mask menu; the effects closed under a heading; Rebake Mesh Maps only when needed
log = []
T.draw_mask_stack(RecP(log), TCtx('PROPS'), u3_mat, u3_fill, explain=False)
check_calls("Mask section", [r for r in log if hasattr(r, "_args")])
props_ = [(r._args[1], r._kw.get("text")) for r in log if getattr(r, "_kind", "") == "prop"]
check(("use_mask", None) in props_ and ("m3d_show_mask", "Show Mask") in props_ and u3_fill.bl_rna.properties["use_mask"].name == "Use Mask",
      "Use Mask (a checkbox named for what it does) and Show Mask: %s" % props_)
check(not any(getattr(r, "_kind", "") == "operator" and r._args[0] in {"m3d.layer_paint_mask", "m3d.layer_mask_remove"} for r in log),
      "no Paint Mask toggle (the thumbnails do it) and no x: Remove Mask is in the mask menu")
check(any(getattr(r, "_kind", "") == "menu" and r._args[0] == "M3D_MT_mask_more" for r in log)
      and any(getattr(r, "_kind", "") == "operator" and r._args[0] == "m3d.layer_mask_invert" for r in log), "Invert Mask and the mask menu")
panels_ = [r for r in log if getattr(r, "_kind", "") == "panel_call"]
check(len(panels_) == 1 and panels_[0].closed and any(getattr(r, "_kind", "") == "template_list" and r._kw.get("show_handles") is False for r in log)
      and "Mask Effects (2)" in [r._kw.get("text") for r in log if getattr(r, "_kind", "") == "label"],
      "the effects are under a heading with their count, closed at first, in a list without handles")
check(not any(getattr(r, "_kind", "") == "operator" and r._args[0] == "m3d.mask_rebake" for r in log), "no Rebake Mesh Maps for a mask that reads no baked maps")
with LY.muted():
    u3_edges = LY.add_effect(u3_fill, 'EDGES')
log = []
T.draw_mask_stack(RecP(log), TCtx('PROPS'), u3_mat, u3_fill, explain=False)
check([r._kw.get("text") for r in log if getattr(r, "_kind", "") == "operator" and r._args[0] == "m3d.mask_rebake"] == ["Rebake Mesh Maps"],
      "...an Edges effect reads one: Rebake Mesh Maps")
check(any("needs the Curvature map: Rebake Mesh Maps" in (r._kw.get("text") or "") for r in log if getattr(r, "_kind", "") == "label"), "...and says which map is missing")
# Delete Effect in the mask menu, for the effect the right-click was on
u3_i = LY.index_of(u3_mat, u3_fill.uid)
check(bpy.ops.m3d.layer_do(action='EFFECT_REMOVE', uid=u3_fill.uid, pick=len(u3_fill.mask_stack) - 1) == {'FINISHED'}
      and 'EDGES' not in [e.kind for e in u3_fill.mask_stack] and u3_fill.mask_stack, "Delete Effect removes the effect under the pointer")
# the Layers menu entry and the operator switch the same state
check(bpy.ops.m3d.layer_paint_mask() == {'FINISHED'} and not u3_fill.paint_mask and T.props_context(TCtx('PROPS')) == 'FILL'
      and bpy.ops.m3d.layer_paint_mask() == {'FINISHED'} and u3_fill.paint_mask and T.props_context(TCtx('PROPS')) == 'MASK',
      "Switch Layer / Mask (Layers menu) flips between the content and the mask, as the thumbnails do")
check(bpy.ops.m3d.layer_mask_remove() == {'FINISHED'} and not u3_fill.paint_mask and T.props_context(TCtx('PROPS')) == 'FILL', "Remove Mask: back on the content")
check(bpy.ops.m3d.layer_mask_add(fill='WHITE') == {'FINISHED'} and u3_fill.paint_mask and bpy.ops.m3d.layer_mask_invert() == {'FINISHED'} and u3_fill.paint_mask,
      "Add Mask and Invert Mask select the mask")
check(bpy.ops.m3d.layer_pick(index=u3_i) == {'FINISHED'} and not u3_fill.paint_mask, "a click on the content thumbnail: the content again")
bpy.ops.object.mode_set(mode='OBJECT')
clean_scene()

# --- Bake page UX: Auto-fit Cage and the two kinds of cage problem, the maps the layers read (Tick), the Layers line, Baked Maps in
# the Assets column, the 2D view that shows a baked map and goes back when Bake Mesh Maps is left.
bq_clean()
tex_ws = W.find_workspace('TEXTURE')
tex_ws.m3d_layout, tex_ws.m3d_page_right = 1, "tex_layers"
# a high poly a little bigger than a coarse low poly: the middles of the low poly's faces lie deeper than its corners
u4_low = bq_sphere("Fit_low", u=24, v=12)
u4_high = bq_sphere("Fit_high", radius=1.05, u=64, v=32)
u4_low.m3d_bake.high = u4_high
VV._view["bvh"].clear()
check(bq_check([(u4_low, [u4_high], 0.06, 0.0)])[2]["tight"] >= 1, "a Cage Distance just past the corners is too tight: the face middles start inside the high poly")
u4_ext, u4_need = VV.fit(bpy.context, [u4_low], [u4_high])
u4_sag = 1.0 - math.cos(math.pi / 12)   # (how far the middle of a face of 12 rings lies below its corners, about)
check(0.05 * 1.1 < u4_ext < (0.05 + 1.5 * u4_sag) * 1.1, "Auto-fit measures how far the high poly sticks out, middles of the faces too, x 1.1: %.4f" % u4_ext)
check(bq_check([(u4_low, [u4_high], u4_ext, 0.0)])[2] == {"tight": 0, "miss": 0, "limited": False}, "...and with it the cage check finds no problem")
check(u4_need > u4_ext, "...the rays need to go at least that far to reach the high poly: %.4f" % u4_need)
for o_ in bpy.data.objects:
    o_.select_set(o_ == u4_low)
bpy.context.view_layer.objects.active = u4_low
u4_low.m3d_bake.extrusion, u4_low.m3d_bake.ray_distance = 0.01, 0.0
VV._view["on"] = True   # (the Bake page's view is up: Auto-fit works on what it checks)
check('UNDO' in VV.M3D_OT_bake_cage_fit.bl_options and bpy.ops.m3d.bake_cage_fit() == {'FINISHED'} and abs(u4_low.m3d_bake.extrusion - u4_ext) < 1e-6
      and u4_low.m3d_bake.ray_distance == 0.0, "Auto-fit Cage sets the Cage Distance of the mesh (one undo step); no Max Ray Distance stays none")
u4_low.m3d_bake.ray_distance = 0.02
check(bpy.ops.m3d.bake_cage_fit() == {'FINISHED'} and abs(u4_low.m3d_bake.ray_distance - u4_need) < 1e-6
      and bq_check([(u4_low, [u4_high], u4_low.m3d_bake.extrusion, u4_low.m3d_bake.ray_distance)])[2]["miss"] == 0,
      "...a Max Ray Distance too short for that cage is raised: %.4f" % u4_low.m3d_bake.ray_distance)
u4_low.scale = (2.0, 2.0, 2.0)
u4_high.scale = (2.0, 2.0, 2.0)
bpy.context.view_layer.update()
VV._view["bvh"].clear()
check(abs(VV.fit(bpy.context, [u4_low], [u4_high])[0] - u4_ext) < 0.1 * u4_ext, "...the Cage Distance is in the units of the mesh (the bake extrudes in object space)")
u4_low.m3d_bake.cage = u4_high
check(bpy.ops.m3d.bake_cage_fit() == {'CANCELLED'}, "a mesh that bakes from a cage mesh has no Cage Distance to fit")
u4_low.m3d_bake.cage = None
# a group: its settings get the fitted distance
u4_gl = bq_sphere("Fg_low", u=24, v=12, role='LOW', group="Fg")
u4_gh = bq_sphere("Fg_high", radius=1.05, u=64, v=32, role='HIGH', group="Fg")
for o_ in bpy.data.objects:
    o_.select_set(o_ == u4_gl)
bpy.context.view_layer.objects.active = u4_gl
check(bpy.ops.m3d.bake_cage_fit() == {'FINISHED'} and abs(bpy.context.scene.m3d_bake_groups["Fg"].extrusion - u4_ext) < 1e-5,
      "...a mesh of a bake group: the group's Cage Distance")
log = bg_draw(T.PROPERTIES_PT_m3d_tx_bake_high, TCtx())
check([r._args[1] for r in log if r._kind == "prop"] == ["extrusion"] and "m3d.bake_cage_fit" in [r._args[0] for r in log if r._kind == "operator"],
      "High Poly has the Cage Distance and Auto-fit Cage")
VV._view.update(areas=2, kinds={"tight": 1, "miss": 1, "limited": False})
log = bg_draw(T.PROPERTIES_PT_m3d_tx_bake_high, TCtx())
check("Cage too tight here: raise Cage Distance Rays find no high poly here: the high poly does not cover it" in " ".join(bg_text(log))
      and "m3d.bake_view_check" in [r._args[0] for r in log if r._kind == "operator"],
      "...under what the check found, each kind of problem with what fixes it (and Check Cage): %s" % bg_text(log))
check(T.M3D_BakeSettings.bl_rna.properties["extrusion"].name == BG.M3D_BakeGroup.bl_rna.properties["extrusion"].name == "Cage Distance", "(it is called Cage Distance everywhere)")
VV.leave(bpy.context)
bq_clean()

# the maps the layers' masks read: a line with Tick on the Bake page when the bake leaves them out, a warning when one is missing
u4_o, u4_m = fresh_cube("U4Tex", '64')
bpy.ops.m3d.tex_project('EXEC_DEFAULT', resolution='64', template='DEFAULT', unwrap=True, bake_after=False)
s_ = u4_o.m3d_bake
s_.resolution, s_.margin, s_.samples, s_.samples_ao = '64', 2, 1, 1
s_.use_normal, s_.use_ao, s_.use_curvature, s_.use_position, s_.use_worldnormal = True, True, False, False, False
u4_item = next(e_ for e_ in m3d_library.entries('MATERIAL') if 'POSITION' in m3d_library.maps_of(e_.item))
check(bpy.ops.m3d.library_apply(item=u4_item.ref) == {'FINISHED'} and bpy.data.images.get("U4Tex_Position") is not None, "(a smart material that reads Position: its maps are baked)")
u4_lines = T.stack_maps(u4_o)
check('POSITION' in [k_ for k_, _l, _m in u4_lines] and not any(m_ for _k, _l, m_ in u4_lines), "the Bake page knows the maps the masks read that the bake leaves out: %s" % u4_lines)
tex_ws.m3d_page_right = "tex_bake"
log = bg_draw(T.PROPERTIES_PT_m3d_tx_bake_maps, TCtx())
u4_layer = dict((k_, l_) for k_, l_, _m in u4_lines)['POSITION']
check("%s uses Position" % u4_layer.name in bg_text(log) and "POSITION" in [r.maps for r in log if r._kind == "operator" and r._args[0] == "m3d.tex_bake_tick"],
      "...a line for each, with Tick: %s" % bg_text(log))
check(bpy.ops.m3d.tex_bake_tick(maps="POSITION") == {'FINISHED'} and s_.use_position and 'POSITION' not in [k_ for k_, _l, _m in T.stack_maps(u4_o)], "Tick ticks it")
s_.use_position = False
bpy.data.images.remove(bpy.data.images["U4Tex_Position"])
check(dict((k_, m_) for k_, _l, m_ in T.stack_maps(u4_o))['POSITION'] is True, "a map that is gone is missing")
log = bg_draw(T.PROPERTIES_PT_m3d_tx_bake_maps, TCtx())
check("%s needs Position" % u4_layer.name in bg_text(log) and any(r._kind == "row" and r.values().get("alert") for r in log), "...the line is a warning")
tex_ws.m3d_page_right = "tex_layers"
log = draw_stub(T.PROPERTIES_PT_m3d_tx_stack, TCtx())
check("Masks need Position" in [r._kw.get("text") for r in log if r._kind == "label"]
      and any(r._kind == "operator" and r._args[0] == "m3d.tex_bake_mode" and r.values().get("on") for r in log), "the Layers panel says it too, with Bake Mesh Maps")
check(bpy.ops.m3d.mask_rebake() == {'FINISHED'} and not any(MK.missing_maps(l_) for l_ in u4_m.m3d_layers), "(Rebake Mesh Maps bakes it again)")
log = draw_stub(T.PROPERTIES_PT_m3d_tx_stack, TCtx())
check(not any("Masks need" in (r._kw.get("text") or "") for r in log if r._kind == "label"), "...and the warning goes")

# Baked Maps: a tile for each baked map with its name and size; while a bake runs only the ones it finished
tex_ws.m3d_page_right = "tex_bake"
with bpy.context.temp_override(workspace=tex_ws):
    check(bpy.ops.m3d.tex_bake_sets() == {'FINISHED'} and tex_ws.m3d_page_right == "tex_bake", "(Normal and AO baked; the dock stays on the Bake page)")
log = bg_draw(T.PROPERTIES_PT_m3d_tx_baked, TCtx('ASSETS'))
u4_maps = [image.name for _l, image in T.mesh_maps(u4_o)]
check([r.name for r in log if r._kind == "operator" and r._args[0] == "m3d.tex_show_image"] == u4_maps and "Normal  64" in bg_text(log) and "AO  64" in bg_text(log),
      "Baked Maps: a tile for each map (a click shows it in the 2D view), named with its size: %s" % bg_text(log))
QQ._run = NS(cancelling=False)
QQ._note["done"] = ["U4Tex_Normal"]
log = bg_draw(T.PROPERTIES_PT_m3d_tx_baked, TCtx('ASSETS'))
check([r.name for r in log if r._kind == "operator" and r._args[0] == "m3d.tex_show_image"] == ["U4Tex_Normal"], "...while a bake runs only the maps it finished")
QQ._run, QQ._note["done"] = None, []
# the 2D view shows a baked map in Bake Mesh Maps, and what it showed before when the dock leaves the Bake page
u4_screen = tex_ws.screens[0]
u4_area = T.view_areas(u4_screen)[1]
u4_space = u4_area.spaces.active
u4_before = bpy.data.images.new("U4Before", 8, 8)
u4_space.image, u4_space.use_image_pin, u4_space.ui_mode = u4_before, False, 'PAINT'
u4_win = NS(workspace=tex_ws, screen=u4_screen)
check(T.show_baked_map(NS(window=u4_win), bpy.data.images["U4Tex_AO"]) and u4_space.image == bpy.data.images["U4Tex_AO"] and u4_space.use_image_pin
      and u4_space.ui_mode == 'VIEW' and tex_ws["m3d_2d_bake"]["image"] == "U4Before", "the 2D view shows a baked map, pinned; what it showed is kept on the workspace")
check(T.show_baked_map(NS(window=u4_win), bpy.data.images["U4Tex_Normal"]) and u4_space.image == bpy.data.images["U4Tex_Normal"] and tex_ws["m3d_2d_bake"]["image"] == "U4Before",
      "...the next map too, and the first state stays kept")
tex_ws.m3d_page_right = "tex_layers"
T.restore_2d(u4_win)
check(u4_space.image == u4_before and not u4_space.use_image_pin and u4_space.ui_mode == 'PAINT' and "m3d_2d_bake" not in tex_ws,
      "leaving Bake Mesh Maps: the 2D view shows what it showed before")
bpy.data.images.remove(u4_before)
clean_scene()
for im_ in [i for i in bpy.data.images if i.name.startswith("U4Tex")]:
    bpy.data.images.remove(im_)

# --- UX part 5 (both pages): the brush settings drawn by the same functions in Sculpt and Texture, keys in the tooltips, narrow
# editors (labels to icons, wrapped hints, fewer asset columns), the bake view's marks that need no colour, the mask effect menu.
p5_o, p5_m = fresh_cube("P5Tex", '64')
bpy.ops.m3d.tex_project('EXEC_DEFAULT', resolution='64', template='DEFAULT', unwrap=True, bake_after=False)
p5_calls = []
p5_shared = ("draw_brush_sliders", "draw_lazy_settings", "stroke_tiles", "draw_alpha", "alpha_grid", "draw_falloff")
p5_real = {n_: getattr(S, n_) for n_ in p5_shared}
for n_, f_ in p5_real.items():   # (record which shared helper each page calls)
    setattr(S, n_, (lambda n_, f_: lambda *a, **k: (p5_calls.append(n_), f_(*a, **k))[1])(n_, f_))
p5_tb = T.image_brush(bpy.context)
p5_tb.use_smooth_stroke = True
p5_logs = {}
for name_, draw_ in (("brush", T.draw_brush), ("alpha", T.draw_alpha), ("advanced", T.draw_advanced)):
    p5_logs[name_] = []
    draw_(Rec(p5_logs[name_]), bpy.context)
    check_calls("Texture " + name_, p5_logs[name_])
p5_tex_calls, p5_calls[:] = list(p5_calls), []
check(set(p5_shared) <= set(p5_tex_calls), "Texture's Properties draw the brush with the shared functions: %s" % p5_tex_calls)
bpy.ops.object.mode_set(mode='SCULPT')
p5_sb = S.sculpt_brush(bpy.context)
p5_sb.use_smooth_stroke = True
p5_slog = []
for cls_ in (S.PROPERTIES_PT_m3d_sc_tuning, S.PROPERTIES_PT_m3d_sc_lazy, S.PROPERTIES_PT_m3d_sc_strokes, S.PROPERTIES_PT_m3d_sc_alpha,
             S.PROPERTIES_PT_m3d_sc_falloff):
    cls_.draw(type("Inst", (), {"layout": Rec(p5_slog)})(), bpy.context)
check_calls("Sculpt tray", p5_slog)
check(set(p5_shared) <= set(p5_calls), "...and Sculpt's tray with the same ones: %s" % p5_calls)
for n_, f_ in p5_real.items():
    setattr(S, n_, f_)


def p5_texts(log, props):
    return [r._kw.get("text") for r in log if r._kind == "prop" and r._args[1] in props]


check(p5_texts(p5_slog, {"size", "unprojected_size", "strength", "hardness"}) == ["Size", "Strength", "Hardness"]
      and p5_texts(p5_logs["brush"], {"size", "unprojected_size", "strength", "hardness"}) == ["Size", "Flow", "Hardness"],
      "the same order and labels: Size, Strength (Flow in Texture), Hardness: %s / %s"
      % (p5_texts(p5_slog, {"size", "strength", "hardness"}), p5_texts(p5_logs["brush"], {"size", "strength", "hardness"})))
check(p5_texts(p5_slog, {"smooth_stroke_radius", "smooth_stroke_factor"}) == p5_texts(p5_logs["brush"], {"smooth_stroke_radius", "smooth_stroke_factor"})
      == ["Distance", "Smoothing"], "Lazy Mouse: Distance and Smoothing in both")
check(p5_texts(p5_slog, {"curve_distance_falloff_preset"}) == p5_texts(p5_logs["advanced"], {"curve_distance_falloff_preset"}) == ["Falloff"]
      and "falloff_shape" in [r._args[1] for r in p5_slog if r._kind == "prop"], "Falloff in both (Sculpt adds its shape)")
check("stroke_method" not in [r._args[1] for r in p5_logs["advanced"] if r._kind == "prop"]
      and len([r for r in p5_logs["brush"] if r._kind == "operator" and r._args[0] == "m3d.stroke_pick"]) == len(S.STROKES),
      "Texture picks the stroke type with the tiles of Sculpt, not a dropdown")
p5_a = [r for r in p5_logs["alpha"] if r._kind == "operator"]
check([r._args[0] for r in p5_a[:2]] == ["m3d.alpha_load", "m3d.alpha_pick"] and p5_a[1]._kw.get("icon") == 'CANCEL'
      and S.ALPHA_NONE in bg_text(p5_logs["alpha"]), "the alpha: what the brush does without one, Load Alpha..., then the tiles (None first)")
check([r._args[0] for r in p5_slog if r._kind == "operator" and r._args[0].startswith("m3d.alpha")][:2] == ["m3d.alpha_load", "m3d.alpha_pick"],
      "...the same in Sculpt")
p5_tb.use_smooth_stroke = p5_sb.use_smooth_stroke = False
bpy.ops.object.mode_set(mode='TEXTURE_PAINT')
check(bpy.ops.m3d.stroke_pick(stroke='DOTS') == {'FINISHED'} and T.image_brush(bpy.context).stroke_method == 'DOTS', "a stroke tile in Texture Paint sets the texture brush")
T.image_brush(bpy.context).stroke_method = 'SPACE'
