_console_mel.bpy = NS(ops=NS(console=NS(history_append=lambda **k: None)))
_console_mel.execute(NS(space_data=p5_sc), False)
p5_sc.history[-1].body = "nope"
_console_mel.execute(NS(space_data=p5_sc), False)
