check(bpy.ops.m3d.sculpt_center_pivot() == {'FINISHED'}, "Center Pivot runs")
bpy.context.view_layer.update()
check(S.off_centre(p2_c) == [] and abs(p2_c.location.x - 0.5) < 1e-4, "...the pivot is in the middle, the mesh where it was")
